package com.candyacademia.spsslite;
import javax.swing.*;import java.awt.*;import java.util.*;import java.util.List;
public final class ChartPanel extends JPanel{
    private static final long serialVersionUID = 1L;
    private final double[] data;private final String title;public ChartPanel(String title,List<Double> values){this.title=title;this.data=values.stream().mapToDouble(Double::doubleValue).toArray();setPreferredSize(new Dimension(720,430));setBackground(Color.WHITE);}
    protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D q=(Graphics2D)g.create();q.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);q.setColor(new Color(35,45,65));q.setFont(getFont().deriveFont(Font.BOLD,18f));q.drawString("Histogram: "+title,30,30);if(data.length==0){q.drawString("No numeric data",30,70);q.dispose();return;}double min=Arrays.stream(data).min().orElse(0),max=Arrays.stream(data).max().orElse(1);int bins=Math.max(5,Math.min(20,(int)Math.ceil(Math.sqrt(data.length))));int[] count=new int[bins];for(double v:data){int i=max==min?0:Math.min(bins-1,(int)((v-min)/(max-min)*bins));count[i]++;}int left=55,top=55,w=getWidth()-85,h=getHeight()-110,peak=Arrays.stream(count).max().orElse(1),bw=Math.max(1,w/bins);q.setColor(new Color(75,125,210));for(int i=0;i<bins;i++){int bh=(int)((double)count[i]/peak*h);q.fillRect(left+i*bw,top+h-bh,bw-2,bh);}q.setColor(Color.DARK_GRAY);q.drawLine(left,top+h,left+w,top+h);q.drawString(String.format("%.3f",min),left,top+h+22);q.drawString(String.format("%.3f",max),left+w-45,top+h+22);q.drawString("N = "+data.length,left,top+h+45);q.dispose();}
}
